// gasmate-htmx: minimal HTMX-compatible implementation
// Supports: hx-get, hx-post, hx-delete, hx-target, hx-swap,
//           hx-vals, hx-include, hx-trigger, hx-confirm
(function(){
  "use strict";

  function doSwap(target, html, mode) {
    if (!target) return;
    if (!mode || mode === "innerHTML") { target.innerHTML = html; processAll(target); }
    else if (mode === "outerHTML") {
      var tmp = document.createElement("div");
      tmp.innerHTML = html;
      var newEl = tmp.firstElementChild;
      target.parentNode.replaceChild(newEl, target);
      if (newEl) processAll(newEl.parentNode);
    }
  }

  function resolveTarget(el) {
    var sel = el.getAttribute("hx-target");
    if (!sel || sel === "this") return el;
    return document.querySelector(sel);
  }

  function gatherVals(el) {
    var vals = {};
    var raw = el.getAttribute("hx-vals");
    if (raw) { try { Object.assign(vals, JSON.parse(raw)); } catch(e){} }
    var inc = el.getAttribute("hx-include");
    if (inc) {
      document.querySelectorAll(inc).forEach(function(f) {
        if (f.name && f.value) vals[f.name] = f.value;
      });
    }
    return vals;
  }

  function formBody(vals) {
    return Object.keys(vals).map(function(k) {
      return encodeURIComponent(k) + "=" + encodeURIComponent(vals[k]);
    }).join("&");
  }

  function request(method, url, vals, target, swapMode) {
    var fullUrl = url;
    var body = null;
    var headers = {};
    if (method === "GET" || method === "DELETE") {
      var qs = formBody(vals);
      if (qs) fullUrl += (url.indexOf("?") >= 0 ? "&" : "?") + qs;
    } else {
      body = formBody(vals);
      headers["Content-Type"] = "application/x-www-form-urlencoded";
    }
    var xhr = new XMLHttpRequest();
    xhr.open(method, fullUrl);
    Object.keys(headers).forEach(function(k){ xhr.setRequestHeader(k, headers[k]); });
    xhr.onload = function() { doSwap(target, xhr.responseText, swapMode); };
    xhr.send(body);
  }

  function bindEl(el) {
    if (el._htmxBound) return;
    var method = (el.getAttribute("hx-post") && "POST") ||
                 (el.getAttribute("hx-get")  && "GET")  ||
                 (el.getAttribute("hx-delete") && "DELETE");
    if (!method) return;
    el._htmxBound = true;
    var url = el.getAttribute("hx-post") || el.getAttribute("hx-get") || el.getAttribute("hx-delete");
    var trigger = el.getAttribute("hx-trigger") ||
      (el.tagName === "SELECT" || el.tagName === "INPUT" ? "change" : "click");
    var swapMode = el.getAttribute("hx-swap") || "innerHTML";
    var confirmMsg = el.getAttribute("hx-confirm");

    el.addEventListener(trigger, function(e) {
      e.preventDefault();
      if (confirmMsg && !window.confirm(confirmMsg)) return;
      var target = resolveTarget(el);
      var vals   = gatherVals(el);
      request(method, url, vals, target, swapMode);
    });
  }

  function processAll(root) {
    var base = root || document;
    ["hx-get", "hx-post", "hx-delete"].forEach(function(attr) {
      base.querySelectorAll("[" + attr + "]").forEach(bindEl);
    });
  }

  document.addEventListener("DOMContentLoaded", function() { processAll(); });
  window.htmx = { process: processAll };
})();
